import re
def blank(text):
 if not isinstance(text,str):text=text[0]
 return re.sub(r'[^\n]',' ',text)
def clean_header(source):
 text=re.sub(r'/\*.*?\*/|//[^\n]*',blank,source,flags=re.S)
 lines=text.splitlines(keepends=True); disabled=0; continuation=False
 for i,line in enumerate(lines):
  d=re.match(r'\s*#\s*(\w+)(.*)',line)
  if disabled:
   if d and d[1] in {'if','ifdef','ifndef'}:disabled+=1
   elif d and d[1]=='endif':disabled-=1
   lines[i]=blank(line)
  elif d and d[1]=='if' and d[2].strip()=='0':
   disabled=1;lines[i]=blank(line)
  elif d or continuation:
   lines[i]=blank(line);continuation=line.rstrip('\n').rstrip().endswith('\\')
 text=''.join(lines)
 text=re.sub(r'(?m)^[ \t]*G_(?:BEGIN|END)_DECLS[^\S\n]*$',blank,text)
 text=re.sub(r'extern\s+"C"\s*\{',blank,text)
 return text
def extract_candidates(source):
 text=clean_header(source);depth=0;start=0;functions=[];extern_variables=[];static_helpers=[]
 for index,char in enumerate(text):
  if char=='{':
   if depth==0:
    frag=text[start:index].strip()
    if re.search(r'\bstatic\b',frag):static_helpers.append(' '.join(frag.split()))
   depth+=1
  elif char=='}':
   depth=max(0,depth-1)
   if depth==0:start=index+1
  elif char==';' and depth==0:
   frag=text[start:index+1];origin=start;start=index+1
   if re.search(r'\btypedef\b',frag):continue
   matches=list(re.finditer(r'\b([a-z_]\w*)\s*\(',frag))
   if matches:
    match=matches[0];prefix=frag[:match.start()].strip()
    if not prefix or re.search(r'\bstatic\b',prefix):continue
    if frag[match.end():].lstrip().startswith('*'):continue
    functions.append({'symbol':match[1],'declaration':' '.join(frag.split()),'line':text.count('\n',0,origin+match.start())+1})
   elif re.search(r'\bextern\b',frag):
    match=re.search(r'\b([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)?;\s*$',frag)
    if match:extern_variables.append({'symbol':match[1],'declaration':' '.join(frag.split()),'line':text.count('\n',0,origin+match.start())+1})
 return functions,extern_variables,static_helpers
